window.ScripturaLexicons.BDAG_PART_0310 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-01\" data-source=\"BDAG\" data-search=\"πρωτεῖος, α, ον adjetivo de primeira qualidade ou categoria; preeminência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτεῖος, α, ον</td><td>adjetivo</td><td>de primeira qualidade ou categoria; preeminência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-02\" data-source=\"BDAG\" data-search=\"πρωτεύω verbo ser o primeiro, ocupar o primeiro lugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτεύω</td><td>verbo</td><td>ser o primeiro, ocupar o primeiro lugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-03\" data-source=\"BDAG\" data-search=\"πρωτοκαθεδρία, ας, ἡ substantivo feminino assento de honra, melhor assento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτοκαθεδρία, ας, ἡ</td><td>substantivo feminino</td><td>assento de honra, melhor assento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-04\" data-source=\"BDAG\" data-search=\"πρωτοκαθεδρίτης, ου, ὁ substantivo masculino ocupante de assento de honra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτοκαθεδρίτης, ου, ὁ</td><td>substantivo masculino</td><td>ocupante de assento de honra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-05\" data-source=\"BDAG\" data-search=\"πρωτοκλισία, ας, ἡ substantivo feminino lugar de honra à mesa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτοκλισία, ας, ἡ</td><td>substantivo feminino</td><td>lugar de honra à mesa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-06\" data-source=\"BDAG\" data-search=\"πρωτόμαρτυς, υρος, ὁ substantivo masculino primeiro mártir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτόμαρτυς, υρος, ὁ</td><td>substantivo masculino</td><td>primeiro mártir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-07\" data-source=\"BDAG\" data-search=\"πρῶτον advérbio, remissão primeiramente; ver πρῶτος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρῶτον</td><td>advérbio, remissão</td><td>primeiramente; ver πρῶτος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-08\" data-source=\"BDAG\" data-search=\"πρῶτος, η, ον adjetivo primeiro, anterior, principal, mais importante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρῶτος, η, ον</td><td>adjetivo</td><td>primeiro, anterior, principal, mais importante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-09\" data-source=\"BDAG\" data-search=\"πρωτοστάτης, ου, ὁ substantivo masculino líder, chefe, cabeça de grupo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτοστάτης, ου, ὁ</td><td>substantivo masculino</td><td>líder, chefe, cabeça de grupo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-10\" data-source=\"BDAG\" data-search=\"πρωτοτόκια, ων, τά substantivo neutro plural direito de primogenitura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτοτόκια, ων, τά</td><td>substantivo neutro plural</td><td>direito de primogenitura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-11\" data-source=\"BDAG\" data-search=\"πρωτότοκος, ον adjetivo primogênito, herdeiro por direito de primogenitura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωτότοκος, ον</td><td>adjetivo</td><td>primogênito, herdeiro por direito de primogenitura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-12\" data-source=\"BDAG\" data-search=\"πρώτως advérbio pela primeira vez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρώτως</td><td>advérbio</td><td>pela primeira vez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-13\" data-source=\"BDAG\" data-search=\"πταίω verbo tropeçar, errar, pecar, arruinar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πταίω</td><td>verbo</td><td>tropeçar, errar, pecar, arruinar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-14\" data-source=\"BDAG\" data-search=\"πτελέα, ας, ἡ substantivo feminino olmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτελέα, ας, ἡ</td><td>substantivo feminino</td><td>olmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-15\" data-source=\"BDAG\" data-search=\"πτέρνα, ης, ἡ substantivo feminino calcanhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτέρνα, ης, ἡ</td><td>substantivo feminino</td><td>calcanhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-16\" data-source=\"BDAG\" data-search=\"πτεροφυέω verbo criar penas ou asas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτεροφυέω</td><td>verbo</td><td>criar penas ou asas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-17\" data-source=\"BDAG\" data-search=\"πτερύγιον, ου, τό substantivo neutro extremidade, borda, pináculo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτερύγιον, ου, τό</td><td>substantivo neutro</td><td>extremidade, borda, pináculo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-18\" data-source=\"BDAG\" data-search=\"πτέρυξ, υγος, ἡ substantivo feminino asa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτέρυξ, υγος, ἡ</td><td>substantivo feminino</td><td>asa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-19\" data-source=\"BDAG\" data-search=\"πτερωτός, (ή), όν adjetivo emplumado, alado; aves BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτερωτός, (ή), όν</td><td>adjetivo</td><td>emplumado, alado; aves</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0310-20\" data-source=\"BDAG\" data-search=\"πτηνός, (ή), όν adjetivo emplumado, alado; aves BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πτηνός, (ή), όν</td><td>adjetivo</td><td>emplumado, alado; aves</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0310-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτεῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτεῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">πρωτεύω</span>) relativo a um grau elevado numa escala de qualidade ou importância, de primeira qualidade/categoria (BGU 950, 4; PLond V, 1764, 7; Sym.) o neutro substantivado no pl. (Ael. Aristid. 38 p. 720 D.; Stephan. Byz. v. <span class=\"greek\">Ἰδουμαῖοι</span>; Sb 6997, 28; PSI 716, 14, onde, infelizmente, o texto se interrompe após <span class=\"greek\">τὰ</span> <span class=\"greek\">πρωτεῖα</span>. O sing. encontra-se em Kaibel 560, 3 [I d.C.]; Jos., Vi. 37; Proclus, Theol. 98 p. 88, 24) <span class=\"greek\">περὶ</span> <span class=\"greek\">πρωτείων</span> pelos primeiros lugares, acerca da preeminência Hs 8, 7, 4; 6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτεύω</span> (cf. <span class=\"greek\">πρωτεῖος</span>; Pla., X. e outros; ins., incl. IMagnSip [IK VIII, 32, 3f]; pap., LXX; Ath., R. 24 p. 78, 4) ocupar a posição mais elevada num grupo, ser o primeiro, ocupar o primeiro lugar <span class=\"greek\">ἵνα</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">πρωτεύων</span> para que viesse a ocupar o primeiro lugar em tudo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:18</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> como Plut., Mor. 9b. O part. pres. como PLips 40 II, 16; POxy 1983, 3; 2 Macc 6:18; 13:15; EpArist 275; Jos., Ant. 9, 167; 20, 182).—New Docs 2, 96; 4, 172. DELG s.v. <span class=\"greek\">πρῶτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτοκαθεδρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτοκαθεδρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πρῶτος</span>, <span class=\"greek\">καθέδρα</span>; escólio a Eur., Orest. 93; Theophanes Conf. 163, 26 de Boor; cf. <span class=\"greek\">προεδρία</span>, acerca de assentos reservados a pessoas em reconhecimento de seus serviços públicos, v. Reader, Polemo 285f) posição ou lugar indicativo de honra especial para a pessoa que o ocupa, assento de honra, melhor assento, desejado pelos fariseus na sinagoga <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:43</a>; 20:46. Igualmente por um falso profeta <span class=\"greek\">θέλει</span> <span class=\"greek\">πρωτοκαθεδρίαν</span> <span class=\"greek\">ἔχειν</span> Hm 11:12.—DELG s.v. <span class=\"greek\">ἕζομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτοκαθεδρίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτοκαθεδρίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. verbete anterior; somente em escritores cristãos) aquele que ocupa um assento de honra (com <span class=\"greek\">οἱ</span> <span class=\"greek\">προηγούμενοι</span>), acerca de dirigentes da congregação Hv 3, 9, 7 (Leutzsch, Hermas 424 n. 420).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτοκλισία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτοκλισία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ins. de Delos [II a.C.]: JHS 54, ’34, 142; Suda) o lugar de honra num banquete, ao lado do dono da casa ou do anfitrião <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:7f</a>; 20:46.—DELG s.v. <span class=\"greek\">κλίνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτόμαρτυς, υρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτόμαρτυς</span>, <span class=\"greek\">υρος</span>, <span class=\"greek\">ὁ</span> acerca de alguém que se distingue especialmente pelo testemunho até à morte, primeiro mártir, acerca de Estêvão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:20</a> v.l. (cf. <span class=\"greek\">Πράξεις</span> <span class=\"greek\">Παύλου</span> Aa I 235 v.l. na forma fem. acerca de Tecla, cujo prestígio é indicado pelos termos descritivos <span class=\"greek\">ἀποστολός</span> e <span class=\"greek\">ἰσαπόστολος</span> na tradição manuscrita; os manuscritos variam, alguns qualificando <span class=\"greek\">πρ</span>. com <span class=\"greek\">ἐν</span> <span class=\"greek\">γυναιξί</span>).—Pap. tardio: New Docs 2, 152.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρῶτον</h1><div class=\"entry-meta\"><span>advérbio, remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρῶτον</span> adv. de <span class=\"greek\">πρῶτος</span>, v. verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρῶτος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρῶτος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom.+; empréstimo na literatura rabínica).</p><p class=\"entry-text\">① relativo a ser o primeiro numa sequência, abrangendo tempo, conjunto (número) ou espaço, primeiro de vários, mas também quando estão envolvidas somente duas pessoas ou coisas (=<span class=\"greek\">πρότερος</span>; exemplos no Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:15</a>; Rdm.2 71f; Thackeray 183; v. também Mlt. 79; 245; B-D-F §62; Rob. 516; 662; e v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a> v.l.).</p><p class=\"entry-text\">ⓐ quanto ao tempo, primeiro, o mais antigo, anterior</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como adj. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρώτης</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a> (sobre a ausência do artigo [também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:5</a> v.l.] v. B-D-F §256; Rob. 793). <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἀπολογία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:16</a> (MMeinertz, Worauf bezieht sich die <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἀπολογία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:16</a>?: Biblica 4, 1923, 390–94). <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">διαθήκη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span> <span class=\"greek\">ἔργα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> 20:5f. <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ὅρασις</span> Hv 3, 10, 3; 3, 11, 2; 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. 2 Cl 14:1.—Substantivado <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. … <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> (Job 8:7): <span class=\"greek\">γίνεται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">χείρονα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:20</a>; Hv 1, 4, 2. <span class=\"greek\">οἱ</span> <span class=\"greek\">πρῶτοι</span> (os que vieram antes, como Artem. 2, 9 p. 93, 19, os que apareceram antes) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:10</a>; cf. v. 8. <span class=\"greek\">ἀπέστειλεν</span> <span class=\"greek\">ἄλλους</span> <span class=\"greek\">δούλους</span> <span class=\"greek\">πλείονας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> 21:36. Cf. 27:64. <span class=\"greek\">πρῶτος</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">νεκρῶν</span> o primeiro a ressuscitar dentre os mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:23</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> o primeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:30</a>. Sobre a autodesignação do Senhor ressuscitado <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔσχατος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:17</a>; 2:8; 22:13; v. <span class=\"greek\">ἔσχατος</span> 2b (<span class=\"greek\">πρ</span>. acerca de Deus: Is 44:6; 48:12).—Como adj. predicativo, onde se pode empregar um advérbio em inglês (ParJer 1:8 <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">ἀνοίξω</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πύλας</span>; B-D-F §243; Rob. 657), como o primeiro = primeiro <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">πρῶτος</span> ele foi o primeiro a vir = ele veio primeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:4</a>; cf. v. 8. <span class=\"greek\">πρῶτος</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">λέγει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:19</a>. <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">περιτομὴν</span> <span class=\"greek\">δούς</span> Abraão foi o primeiro a praticar a circuncisão B 9:7. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πρῶτοι</span> <span class=\"greek\">κτισθέντες</span> os anjos que foram criados primeiro Hv 3, 4, 1; Hs 5, 5, 3.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:19</a>; AcPlCor 2:9.—<span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">πρώτῳ</span> em mim como o primeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>.—Usado com gen. de comparação (Ocelus Luc. 3 <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντός</span> <span class=\"greek\">ἐστιν</span>=anterior ao Todo; Manetho 1, 329; Athen. 14, 28 p. 630c códices) <span class=\"greek\">πρῶτός</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἦν</span> ele era anterior a mim = antes de mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:15</a>, 30 (PGM 13, 543 <span class=\"greek\">σοῦ</span> <span class=\"greek\">πρῶτός</span> <span class=\"greek\">εἰμι</span>.—Também Ep. 12 de Apolônio de Tiana: Philostrat. I p. 348, 30 <span class=\"greek\">τὸ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τάξει</span> <span class=\"greek\">δεύτερον</span> <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">πρῶτον</span>). Assim talvez também <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μεμίσηκεν</span> 15:18 (v. <span class=\"greek\">β</span> abaixo) e <span class=\"greek\">πάντων</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐκτίσθη</span> Hv 2, 4, 1.—Em regra, o elemento posterior é da mesma natureza geral que aquele que o precede. Mas também pode ser algo inteiramente diferente, até mesmo seu exato oposto: <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἠθέτησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:12</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> <span class=\"greek\">ἀφῆκες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:4</a>.—Usado elipticamente <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> (isto é, <span class=\"greek\">ἡμέρα</span> semelhantemente Polyb. 5, 19, 1; 18, 27, 2 <span class=\"greek\">τῇ</span> <span class=\"greek\">πρώτῃ</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:17</a>. <span class=\"greek\">πρώτῃ</span> <span class=\"greek\">σαββάτου</span> no primeiro dia da semana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:9</a>. Em algumas das passagens acima mencionadas a ideia de sequência poderia ser predominante.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. o neutro <span class=\"greek\">πρῶτον</span> como adv., quanto ao tempo, primeiro, em primeiro lugar, antes, anteriormente, para começar (Peripl. Eryth. 4; Chariton 8, 2, 4; ApcEsdr 3:11; Just., D. 2, 4) <span class=\"greek\">πρῶτον</span> <span class=\"greek\">πάντων</span> antes de tudo Hv 5:5a. <span class=\"greek\">ἐπίτρεψόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ἀπελθεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θάψαι</span> permite-me primeiro ir e sepultar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:21</a>. <span class=\"greek\">συλλέξατε</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ζιζάνια</span> recolhei primeiro o joio 13:30. Cf. 17:10, 11 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:27</a>; 9:11f; 13:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:59</a>, 61; 12:1 (primeiro Jesus fala a seus discípulos, e somente depois [v. 15] ao povo. Se se prefere tomar <span class=\"greek\">πρ</span>. com o que segue, como é possível, tem a acepção 2a); 14:28, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:51</a>; 18:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:24</a> e outros no NT; B 15:7; Hv 3, 1, 8; 3, 6, 7; 3, 8, 11; 5:5b. <span class=\"greek\">τότε</span> <span class=\"greek\">πρῶτον</span> então pela primeira vez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:26</a> D. <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">τότε</span> primeiro … e então (Sir 11:7; Jos., Ant. 13, 187) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:24</a>; 7:5; 12:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:42</a>; IEph 7:2. <span class=\"greek\">τότε</span> é correlativo de <span class=\"greek\">πρῶτον</span> sem <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10</a> v.l. Igualmente <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">εἶτα</span> (<span class=\"greek\">εἶτεν</span>) primeiro … então (Just., D. 33, 2 e outros; v. <span class=\"greek\">εἶτα</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:10</a>; B 6:17. <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">ἔπειτα</span> (<span class=\"greek\">ἔπειτα</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a>. <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">μετὰ</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:9</a>, v. v. 12. <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">εἶτα</span> … <span class=\"greek\">μετὰ</span> <span class=\"greek\">ταῦτα</span> 1 Cl 23:4; 2 Cl 11:3 (em ambos os casos o mesmo enunciado profético de origem desconhecida). <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δευτέρῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:12</a>.—Pleonasticamente <span class=\"greek\">πρῶτον</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀρίστου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:38</a>.—Com gen. (Chariton 5, 4, 9 cód. <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγων</span>=antes de se chegar às palavras) <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μεμίσηκεν</span> odiou-me antes de (odiar) vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:18</a> (mas v. 1a<span class=\"greek\">α</span>).—Com o artigo <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> (Hom. e outros; Jos., Ant. 8, 402; 14, 205) pela primeira vez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:40</a>; 19:39; a princípio (Diod S 1, 85, 2; Jos., Ant. 2, 340) 12:16; 2 Cl 9:5. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span> (Hom. e outros; Appian, Syr. 15 §64; Ps.-Phoc. 8) pela primeira vez, a princípio MPol 8:2.</p><p class=\"entry-text\">ⓑ quanto ao número ou à sequência (o domínio em que este sentido é válido não pode ser delimitado com certeza em relação ao domínio 1a<span class=\"greek\">α</span>)</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como adj. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:28</a>; 22:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:18</a>; 16:5; 19:16; 20:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:10</a>; 13:33 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:7</a>; 8:7; 21:19; Hs 9, 1, 5. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">δεύτερον</span> (Alex. Aphr., An. p. 28, 9 Br.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:9</a>. Sobre <span class=\"greek\">πρώτης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μερίδος</span> <span class=\"greek\">Μακεδονίας</span> <span class=\"greek\">πόλις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:12</a> v. <span class=\"greek\">μερίς</span> 1 e RAscough, NTS 44, ’98, 93–103.—Uma vez que <span class=\"greek\">πρῶτος</span> pode representar <span class=\"greek\">πρότερος</span> (v. 1 no início; também Mlt-Turner 32), de modo algum se segue de <span class=\"greek\">τὸν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:1</a> que o autor de Lucas e de Atos necessariamente tivesse planejado escrever um terceiro livro (Zahn, NKZ 28, 1917, 373ff, Comm. 1919, 16ff sustenta que ele planejava escrever um terceiro volume; contra essa opinião v. EGoodspeed, Introd. to the NT ’37, 189; Haenchen e outros.—Athenaeus 15, 701c menciona o primeiro dos dois livros de Clearco sobre provérbios com as palavras <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">προτέρῳ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">παροιμιῶν</span>, mas 10, 457c com <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρώτῳ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">παροιμιῶν</span>. Diod S 1, 42, 1 a primeira metade de uma obra em duas partes é chamada <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">βίβλος</span> e 3, 1, 1 menciona uma divisão em <span class=\"greek\">πρώτη</span> e <span class=\"greek\">δευτέρα</span> <span class=\"greek\">βίβ</span>. Em 13, 103, 3 a designação para a primeira de duas obras varia entre <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">σύνταξις</span> e <span class=\"greek\">ἡ</span> <span class=\"greek\">προτέρα</span> <span class=\"greek\">ς</span>. V. Haenchen sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:1</a>).—<span class=\"greek\">πρῶτος</span> também é usado sem nenhuma ideia de que a série deva continuar: <span class=\"greek\">τὸν</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ἰχθύν</span> o primeiro peixe que aparecer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:27</a>. <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἀπογραφὴ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐγένετο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:2</a>, igualmente, não aponta para recenseamentos adicionais no futuro, mas retrospectivamente para um tempo em que não havia nenhum (Ael. Aristid. 13 p. 227 D. <span class=\"greek\">παράκλησις</span> <span class=\"greek\">αὕτη</span> [=desafio para um combate naval] <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐγένετο</span>; sobre a teoria da interpolação v. JWinandy, RB 104, ’97, 372–77; cf. BPearson, CBQ, ’99, 262--82).—<span class=\"greek\">τὰ</span> <span class=\"greek\">τείχη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span> Hs 8, 6, 6 não contrapõe os ‘primeiros muros’ a outros muros; antes distingue os únicos muros na imagem (Hs 8, 7, 3; 8, 8, 3), como um edifício, da torre como o outro edifício.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. adv., o neutro <span class=\"greek\">πρῶτον</span> acerca da sequência em enumerações (nem sempre claramente distinguido da acepção 1a<span class=\"greek\">β</span>) primeiro <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ἀποστόλους</span>, <span class=\"greek\">δεύτερον</span> <span class=\"greek\">προφήτας</span>, <span class=\"greek\">τρίτον</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:28</a> (Mitt-Wilck. I/2, 20 II, 10ff [II d.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. … <span class=\"greek\">τὸ</span> <span class=\"greek\">δεύτερον</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span>. Sem o artigo 480, 12ff [II d.C.]; Diod S 36, 7, 3; Tat. 40, 1). V. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:17</a>.—Não raro Paulo começa com <span class=\"greek\">πρῶτον</span> <span class=\"greek\">μέν</span> sem prosseguir a série, pelo menos formalmente (B-D-F §447, 4; Rob. 1152. Para <span class=\"greek\">πρ</span>. sem continuação v. Plat., Ep. 7, 337b, Plut., Mor. 87b; Jos., Ant. 1, 182; Ath. 27, 1 <span class=\"greek\">πρῶτα</span> <span class=\"greek\">μέν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a>; 3:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a>. V. também 2 Cl 3:1.</p><p class=\"entry-text\">ⓒ quanto ao espaço, exterior, anterior <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> a tenda exterior, isto é, o lugar santo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:2</a>; cf. vv. 6, 8.</p><p class=\"entry-text\">② relativo à proeminência, primeiro, principal, mais importante, mais proeminente</p><p class=\"entry-text\">ⓐ adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. acerca de coisas (Ocellus [II a.C.] 56 Harder [1926] <span class=\"greek\">πρώτη</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μεγίστη</span> <span class=\"greek\">φυλακή</span>; Ael. Aristid. 23, 43 K.=42 p. 783 D.: <span class=\"greek\">πόλεις</span>; Ezk 27:22; PsSol 17:43; <span class=\"greek\">χρυσίον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τίμιον</span>; JosAs 15:10) <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐντολή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:38</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:29</a>. <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">πάντων</span> v. 28 (OLehmann, TU 73, ’59, 557–61 [rabínico]; CBurchard, ZNW 61, ’70, cita JosAs 15:10; 18:5). Sem força superlativa <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπαγγελίᾳ</span> um mandamento de grande importância, ao qual está associada uma promessa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:2</a> (a tradução habitual ‘primeiro mandamento com promessa’ [NRSV, REB e outros] perde de vista o fato de que Ex 20:4–6=Dt 5:8–10 tem uma promessa implícita da mesma espécie daquela de Ex 20:12=Dt 5:16. <span class=\"greek\">πρ</span>. aqui é mais bem entendido no mesmo sentido de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:29</a> acima). <span class=\"greek\">στολὴν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> a veste especial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:22</a> (JosAs 15:10).—<span class=\"greek\">ἐν</span> <span class=\"greek\">πρώτοις</span> entre as primeiras coisas = as mais importantes, isto é, como de primeira importância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:3</a> (Pla., Pol. 522c <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πρώτοις</span> <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">μανθάνειν</span>; Epict., Ench. 20; Mitt-Wilck I/2, 14 II, 9 <span class=\"greek\">ἐν</span> <span class=\"greek\">πρώτοις</span> <span class=\"greek\">ἐρωτῶ</span> <span class=\"greek\">σε</span>; Josh 9:2d).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. acerca de pessoas (Dio Chrys. 19 [36], 35 <span class=\"greek\">πρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">μέγιστος</span> <span class=\"greek\">θεός</span>; TestAbr B 4 p. 108, 18 [Stone p. 64]; ApcSed 5:2; Jos., Ant. 15, 398; Just., A I, 60, 5 e outros <span class=\"greek\">τὸν</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">θεόν</span>) <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">θέλῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">πρῶτος</span> quem quer que deseje ser o primeiro entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:44</a>; cf. 9:35. <span class=\"greek\">πρῶτος</span> <span class=\"greek\">Σίμων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:2</a> não pretende indicar a posição de Simão na lista, uma vez que não se seguem outros números, mas destacá-lo como o mais proeminente dos doze. Com gen. <span class=\"greek\">ὧν</span> (=<span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτωλῶν</span>) <span class=\"greek\">πρῶτός</span> <span class=\"greek\">εἰμι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:15</a>. Pl. (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πρῶτοι</span> em contraste com (<span class=\"greek\">οἱ</span>) <span class=\"greek\">ἔσχατοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:30</a>; 20:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:35</a>; 10:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:30</a>; Ox 654, 25f (cf. GTh 4; semelhantemente Sallust. 9 p. 16, 21f <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐσχάτοις</span> … <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρώτοις</span>; v. <span class=\"greek\">ἔσχατος</span> 2).—<span class=\"greek\">αἱ</span> <span class=\"greek\">πρώται</span> mulheres proeminentes (na expressão <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλίγαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:4</a> (v. New Docs 1, 72). <span class=\"greek\">οἱ</span> <span class=\"greek\">πρῶτοι</span> os homens mais proeminentes, os homens de maior destaque, com gen. de lugar (Jos., Ant. 7, 230 <span class=\"greek\">τῆς</span> <span class=\"greek\">χώρας</span>) <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.50\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:50</a> (em formulação semelhante a <span class=\"greek\">πολλὰς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">γυναῖκας</span> <span class=\"greek\">εὐγενεῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">ἤισχυναν</span>=‘desonraram muitas mulheres de nobre nascimento, bem como homens de posição elevada’ Theopomp.: 115 Fgm. 121 Jac. p. 563, 33f), ou de um grupo (Strabo 13, 2, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">φίλων</span>; Jos., Ant. 20, 180) <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> (Jos., Ant. 11, 141) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:47</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:2</a>; 28:17. Sobre <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νήσου</span> v. 7 (<span class=\"greek\">πρῶτος</span> <span class=\"greek\">Μελιταίων</span> IGR I, 512=IG XIV, 601; cf. CB I/2, 642 n.º 535 <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span>; p. 660 n.º 616; SEG XLI, 1345, 14f; cf. CIL X, 7495, 1; v. Hemer, Acts 153, n. 152; Warnecke, Romfahrt 119ff) v. <span class=\"greek\">Πόπλιος</span>.</p><p class=\"entry-text\">ⓑ adv. <span class=\"greek\">πρῶτον</span> quanto ao grau, em primeiro lugar, acima de tudo, especialmente (Jos., Ant. 10, 213) <span class=\"greek\">ζητεῖτε</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:33</a>. <span class=\"greek\">Ἰουδαίῳ</span> <span class=\"greek\">τε</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἕλληνι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:16</a>; cf. 2:9f.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:20</a>; 3:3. Acerca dos cristãos macedônios <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">ἔδωκαν</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμῖν</span> deram-se a si mesmos antes de tudo ao Senhor e (depois) a nós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:5</a>. <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">πάντων</span> antes de tudo exorto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a>.—B. 939. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτοστάτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτοστάτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πρῶτος</span>, <span class=\"greek\">ἵστημι</span>; Thu. e outros; pap. [tardio, New Docs 4, 244]; Job 15:24) ‘aquele que está em primeiro lugar’, pessoa que está à frente de um grupo, líder, provavelmente no sentido de cabeça de uma facção <span class=\"greek\">πρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ναζωραίων</span> <span class=\"greek\">αἱρέσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a>.—DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτοτόκια, ων, τά</h1><div class=\"entry-meta\"><span>substantivo neutro plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτοτόκια</span>, <span class=\"greek\">ων</span>, <span class=\"greek\">τά</span> (<span class=\"greek\">πρωτότοκος</span>; B-D-F §120, 1; Mlt-H. 279) privilégios associados à condição de primogênito, direito de primogenitura, direito do filho primogênito (Gen 27:36; Philo, Leg. All. 2, 47, Sacr. Abel. 120 e outros na narrativa de Esaú) <span class=\"greek\">Ἠσαῦ</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">βρώσεως</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">ἀπέδοτο</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρωτοτόκια</span> <span class=\"greek\">ἑαυτοῦ</span> Esaú vendeu seu direito de primogenitura por uma única refeição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:16</a> (Gen 25:33).—DELG s.v. <span class=\"greek\">τίκτω</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωτότοκος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωτότοκος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πρῶτος</span>, <span class=\"greek\">τόκος</span>; Sb 6647 [5 a.C.; v. WMichaelis em 2a: p. 314f]; Kaibel 460, 4; 730, 3; PLips 28, 16; PGM 36, 312; Anth. 8, 34; 9, 213; LXX; TestReub, JosAs; SibOr 3, 627 Philo, Cher. 54 e outros; Jos., Ant. 4, 71; Just., Tat., Mel., Iren.) ‘primogênito, herdeiro por direito de primogenitura’.</p><p class=\"entry-text\">① lit. relativo à ordem de nascimento, primogênito <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. (PLips loc. cit. <span class=\"greek\">υἱὸν</span> <span class=\"greek\">γνήσιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρωτότοκον</span>; Gen 25:25 e outros na LXX; JosAs 1:11; <span class=\"greek\">Σὴθ</span> <span class=\"greek\">τρίτος</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐστίν</span> Did., Gen 147, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:25</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:7</a> (JFrey, La signification du terme <span class=\"greek\">πρ</span>. d’après une inscription juive: Biblica 2, 1930, 373–90; CIJ II 1510, 6; Boffo, Iscrizioni 156–65; New Docs 163); cf. B 13:5 (Gen 48:18). <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. os primogênitos=todos os primogênitos (<span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. Ex 22:28; Num 18:15 e outros; Just., D. 84, 1; 111, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a> (cf. Ex 11:5). <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">προβάτων</span> os primogênitos das ovelhas 1 Cl 4:1 (Gen 4:4). A posição especial de que gozava um filho primogênito como herdeiro por direito de primogenitura em Israel é um componente implícito de <span class=\"greek\">πρ</span>. em referência a tal filho e desempenha papel dominante em</p><p class=\"entry-text\">② relativo a ter a posição especial associada a um primogênito, primogênito, extensão fig. de 1</p><p class=\"entry-text\">ⓐ acerca de Cristo, como primogênito de uma nova humanidade que há de ser glorificada, assim como seu Senhor exaltado é glorificado <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">ἀδελφοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:29</a>. Também simplesmente <span class=\"greek\">πρωτότοκος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:8</a> v.l. Esta expressão, admiravelmente adequada para descrever Jesus como aquele que procede de Deus para fundar a nova comunidade de crentes, é também usada em alguns casos nos quais a força do elemento -<span class=\"greek\">τοκος</span> parece, à primeira vista, incerta, mas v. o comentário sobre posição no fim de 1 (cf. o salmo naasseno originalmente politeísta em Hippol., Ref. 5, 10, 1 e também Ex 4:22; Ps. 88:28) (<span class=\"greek\">ὁ</span>) <span class=\"greek\">πρ</span>. (<span class=\"greek\">ἐκ</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">νεκρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:5</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">κτίσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:15</a> (cf. Orig., C. Cels. 6, 17, 38; Theoph. Ant. 2, 22 [p. 154, 18]; v. JGewiess, Christus u. d. Heil nach d. Kol.: diss. Breslau ’32; ECerny, Firstborn of Every Creature [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:15</a>]: diss. Baltimore ’38; Romualdus, Studia Cath. 18, ’42, 155–71; WMichaelis, D. Beitrag d. LXX zur Bedeutungsgeschichte von <span class=\"greek\">πρ</span>.: ADebrunner Festschr. ’54, 313–20, ZST 23, ’54, 137–57; AArgyle, ET 66, ’54, 61f, cf. 124f, 318f; NKehl, D. Christushymnus im Kol., ’67, 82–98).</p><p class=\"entry-text\">ⓑ acerca de seres humanos comuns</p><p class=\"entry-text\"><span class=\"greek\">α</span>. acerca do povo de Deus (JosAs 21:3 <span class=\"greek\">Ἰωσὴφ</span> … <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>.) acerca da assembleia dos primogênitos (v. Ex 4:22) no céu <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">πρωτοτόκων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:23</a>. Alguns interpretam esta expressão como referência a anjos. Sobre as diversas interpretações v. OMichel, comm. ad loc.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. acerca de um dissidente notório <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σατανᾶ</span> Pol 7:1 (NDahl, D. Erstgeborene Satans u. d. Vater des Teufels: EHaenchen Festschr., ’64, 70–84). Especificamente acerca de Marcião, segundo um dito de Policarpo, EpilMosq 3 (cf. Iren. 3, 3, 4 [Harv. II 14, 2]); v. também a expressão hebraica correspondente em HZucker, Studien z. jüd. Selbstverwaltg. im Altert. ’36, 135.—DELG s.v. <span class=\"greek\">τίκτω</span> B. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρώτως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρώτως</span> adv. (<span class=\"greek\">πρῶτος</span>; Aristot. e outros; OGI 602, 4; UPZ 110, 81 [164 a.C.]; POxy 1023, 3f [II d.C.]; 1267, 10; ViJer 14 [p. 73, 14 Sch.]; EpArist 4; Ath., R. 25 p. 78, 31) pela primeira vez (assim Polyb. 6, 5, 10; Diod S 4, 24, 1; IPriene 117, 39; SIG 797, 16; PRyl 235, 11; Jos., Bell. 2, 25. V. Lob., Phryn. p. 311f; Crönert 193; B-D-F §102, 5; Mlt-H. 163) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:26</a> (v.l. <span class=\"greek\">πρῶτον</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πταίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πταίω</span> 1 aor. <span class=\"greek\">ἔπταισα</span>; perf. <span class=\"greek\">ἔπταικα</span> LXX; part. aor. pass. masc. ac. <span class=\"greek\">πταισθέντα</span> (Papias v.l.) (Pind. e outros; ins., pap., LXX; TestJob 38:1; ApcSed 1:1; EpArist, Philo, Joseph.; transitivo somente na Catena sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:11</a> [JCramer I 231] em referência a Papias [3:2] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμάξης</span> <span class=\"greek\">πταισθέντα</span> atingido pela carroça) em nossa literatura somente intr.</p><p class=\"entry-text\">① perder a firmeza dos pés, tropeçar, dar um passo em falso (X., An. 4, 2, 3 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πέτρας</span>; Polyb. 31, 11, 5 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λίθον</span>; Jos., Bell. 6, 64 <span class=\"greek\">πρὸς</span> <span class=\"greek\">πέτρᾳ</span>), em linguagem figurada (como Aeschyl., Hdt. e outros) na qual o sentido lit. é claramente discernível. Abs. (Maximus Tyr. 34, 2e) <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔπταισαν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">πέσωσιν</span>; não tropeçaram a ponto de cair em ruína, não é? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:11</a>. O ‘tropeçar’ significa cometer um erro, desviar-se, pecar (Pla., Theaet. 160d e outros; abs. Arrian, Anab. 4, 9, 6; M. Ant. 7, 22 <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">φιλεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πταίοντας</span>; POxy 1165, 11 <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἔπταισαν</span> <span class=\"greek\">εἴτε</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔπταισαν</span>=‘quer tenham cometido um erro, quer não’; Dt 7:25; TestJob 38:1; ApcSed 1:1; EpArist 239; Philo, Leg. All. 3, 66) <span class=\"greek\">πολλὰ</span> <span class=\"greek\">πταίομεν</span> cometemos muitos pecados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:2a</a> (ApcSed 1:1); <span class=\"greek\">πτ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνί</span> pecar num aspecto (somente) 2:10. <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> no que se diz 3:2b.</p><p class=\"entry-text\">② sofrer um desastre, arruinar-se, perder-se (Hdt. 9, 101; Aristot., Rhet. 3 e outros; Diod S 15, 33, 1 e outros; Philo, De Jos. 144; Jos., Ant. 7, 75; 14, 434) acerca da perda da salvação 2 Pt 1:10: o aor., como nas referências acima citadas, fornece o componente semântico de desastre culminante. Mas a acepção 1 também tem defensores.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτελέα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτελέα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hom. [<span class=\"greek\">πτελέη</span>] e outros; Sym. Is 41:19) olmo, como suporte para videiras Hs 2:1ff.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτέρνα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτέρνα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (variante da forma anterior <span class=\"greek\">πτέρνη</span>; Hom. e outros; LXX; ApcMos 26; Jos., Ant. 1, 258 [segundo Gen 25:26]; SibOr 1, 63; v. B-D-F §43, 2) calcanhar <span class=\"greek\">ἐπαίρειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πτ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> levantar o calcanhar contra alguém para desferir um chute malicioso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:18</a> (com alguma relação com uma forma de Ps 40:10 que, na LXX, termina com <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">πτερνισμόν</span>).—DELG s.v. <span class=\"greek\">πτέρνη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτεροφυέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτεροφυέω</span> (<span class=\"greek\">πτερόν</span>, <span class=\"greek\">φύω</span>) fut. 3 pl. <span class=\"greek\">πτεροφυήσουσιν</span> Is 40:3 adquirir/desenvolver penas/asas (Plut., Mor. 751f acerca de Eros; Lucian, Icar. 10; Olympiodorus, Life of Plato p. 2 Westermann; Horapollo 1, 55; Is 40:31.—Em sentido fig. já em Pla.) <span class=\"greek\">σκώληξ</span> … <span class=\"greek\">πτεροφυεῖ</span> 1 Cl 25:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτερύγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτερύγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πτέρυξ</span>; Aristot. e outros; Aeneas Tact. 1440; ins., LXX; TestSol 22:8) diminutivo de <span class=\"greek\">πτέρυξ</span> ‘asa’; serve para designar a ponta ou extremidade de qualquer coisa, extremidade, borda <span class=\"greek\">τὸ</span> <span class=\"greek\">πτερύγιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span> algo como o pináculo ou cume do templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:9</a> (também em Hegesipo: Eus., HE 2, 23, 11. Rufino tem para isto ‘excelsus locus pinnae templi’.—V. Theod. Da 9:27 [leitura de uma duplicata; v. ed. JZiegler ’54 p. 191] e M-JLagrange, RB 39, 1930, 190). JJeremias, ZDPV 59, ’36, 195–208 propõe: ‘o lintel ou a superestrutura de uma porta do templo’. Mas para os gregos a palavra mais facilmente compreendida para isso seria <span class=\"greek\">ὑπέρθυρον</span> (Parmenides [VI/V a.C.], Fgm. 1, 12 [28 B Diels]; Hdt. 1, 179 e outros; também Herodas 2, 65; Artem. 2, 10 p. 97, 26; 4, 42 p. 226, 8.—Jos., Bell. 5, 201 numa descrição do templo de Jerusalém).—DELG s.v. <span class=\"greek\">πτερόν</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτέρυξ, υγος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτέρυξ</span>, <span class=\"greek\">υγος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πτερόν</span> ‘pena’; cf. <span class=\"greek\">πέτομαι</span>; Hom. e outros; SIG 1167, 1–5; POxy 738, 10; LXX, Test12Patr, JosAs, GrBar; ApcSed 2:4; ApcMos 26; Jos., Ant. 8, 72) asa, de aves <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:14</a> (Test Napht 5:6 <span class=\"greek\">πτ</span>. <span class=\"greek\">ἀετοῦ</span>). As quatro estranhas criaturas de Rv têm seis asas cada uma (cf. Is 6:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:8</a>. Acerca dos gafanhotos apocalípticos <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πτ</span>. o ruído das asas 9:9.—B. 245. DELG s.v. <span class=\"greek\">πτερόν</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτερωτός, (ή), όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτερωτός</span>, (<span class=\"greek\">ή</span>), <span class=\"greek\">όν</span> (<span class=\"greek\">πτερόν</span> ‘pena’, <span class=\"greek\">πέτομαι</span>; Aeschyl., Hdt. e outros; LXX; TestSol) relativo a ter penas, emplumado, alado, substantivado <span class=\"greek\">τὰ</span> <span class=\"greek\">πτερωτά</span> criaturas aladas, aves (Aeschyl., Suppl. 510; Eur., Hel. 747.—Ps 77:27 e 148:10 na expressão <span class=\"greek\">πετεινὰ</span> <span class=\"greek\">πτερωτά</span>, <span class=\"greek\">πετεινά</span> é claramente o substantivo. O masc. <span class=\"greek\">οἱ</span> <span class=\"greek\">πτερωτοί</span> ocorre no mesmo sentido: Eur., Bacch. 257) <span class=\"greek\">ἐκτείνεται</span> <span class=\"greek\">δίκτυα</span> <span class=\"greek\">πτερωτοῖς</span> B 5:4 (Pr 1:17).—DELG s.v. <span class=\"greek\">πτερόν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0310-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πτηνός, (ή), όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πτηνός</span>, (<span class=\"greek\">ή</span>), <span class=\"greek\">όν</span> (cf. o aor. <span class=\"greek\">ἔπτην</span> de <span class=\"greek\">πέτομαι</span>; Pind. e outros) relativo a ter penas, emplumado, alado, substantivado <span class=\"greek\">τὰ</span> <span class=\"greek\">πτηνά</span> as aves (Aeschyl., Pla. e outros; Aq. Job 5:7; EpArist 145; 146; 147; Philo; SibOr 3, 370) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>.—DELG s.v. <span class=\"greek\">πέτομαι</span>. M-M.</p></section></article>"};
